export function StickyCta({
  ctaText = "{{ctaText}}",
  position = "{{position}}",
  accent = "{{accent}}",
  showDismiss = {{showDismiss}},
}) {
  const corner = position === "bottom-right";
  return (
    <div style={{ position: "relative", height: 200, overflow: "auto", border: "1px solid #24143022",
      borderRadius: 12, font: "14px system-ui, sans-serif", color: "#241430" }}>
      <div style={{ padding: 16 }}>
        <p style={{ margin: "0 0 60px", color: "#241430aa" }}>Scroll this frame &mdash; the call to action stays pinned.</p>
        <p style={{ margin: "0 0 60px", color: "#241430aa" }}>Page content keeps flowing underneath it.</p>
        <p style={{ margin: "0 0 60px", color: "#241430aa" }}>More content here to make the frame scrollable.</p>
      </div>
      <div style={{ position: "sticky", bottom: 0, display: "flex", alignItems: "center", justifyContent: "space-between",
        gap: 12, color: "#FAF7F2", fontWeight: 700, background: accent,
        width: corner ? "fit-content" : "100%", padding: corner ? "12px 18px" : "14px 18px",
        borderRadius: corner ? 999 : 0, margin: corner ? "0 12px 12px auto" : 0 }}>
        <span>{ctaText}</span>
        {showDismiss && <button type="button" aria-label="Dismiss" style={{ background: "none", border: "none", color: "inherit", fontSize: 16, cursor: "pointer" }}>&times;</button>}
      </div>
    </div>
  );
}
